import requests

# 1. Coloque a sua string Base64 COMPLETA dentro dessas aspas triplas (ela pode ter o tamanho que for)
IMAGEM_BASE64 = """"""

# 2. Configura os dados que vão para o banco
payload = {
    "user_id": "Polyana",
    "image": IMAGEM_BASE64
}

# 3. Dispara o envio para a sua API Node (porta 3001)
try:
    print("🚀 Enviando registro para a API...")
    resposta = requests.post("http://localhost:3001/api/face/register", json=payload)
    print(f"📡 Status Code: {resposta.status_code}")
    print(f"📥 Resposta do Servidor: {resposta.json()}")
except Exception as e:
    print(f"❌ Erro ao conectar: {e}")